async function main(ctx) {
  const i = ctx.input || {};
  const owner = String(i.owner || '').trim();
  const repo = String(i.repo || '').trim();
  if (!owner) throw new Error('owner is required');
  if (!repo) throw new Error('repo is required');
  return {
    owner,
    repo,
    base: String(i.base || '').trim() || null,
    requestedBranch: String(i.branch || '').trim() || null
  };
}

async function main(ctx) {
  const r = ctx.lastOutputOf('confirm') || {};
  const n = ctx.lastOutputOf('normalize_input') || {};
  const lines = String(r.stdout || '').split('\n').map((s) => s.trim()).filter(Boolean);
  const ok = Number(r.exitCode ?? 1) === 0;
  return {
    success: ok,
    owner: n.owner,
    repo: n.repo,
    base: n.base,
    branch: lines[0] || n.requestedBranch || null,
    head: lines[1] || null,
    remote: lines[2] || null,
    message: ok ? 'Workspace ready. Use the returned branch when opening the PR.' : (r.stderr || 'checkout failed')
  };
}
